command(@'
// ============================================================================
// COSMIC EXPLORER - 3D THREE.JS SOLAR SYSTEM ENGINE & NASA HUD
// High-performance WebGL planetary simulation with orbital physics & fly-to camera
// ============================================================================

import { SOLAR_SYSTEM_DATA } from "./data/spaceData.js";
import { sound } from "./audio.js";
import { auth } from "./auth.js";

export class SolarSystemEngine {
  constructor(containerId) {
    this.container = document.getElementById(containerId);
    this.scene = null;
    this.camera = null;
    this.renderer = null;
    this.controls = null;
    this.planets = {};
    this.orbitLines = [];
    this.asteroidBelt = null;
    this.animationFrameId = null;
    this.timeSpeed = 1.0;
    this.isPaused = false;
    this.selectedPlanetId = null;
    this.raycaster = null;
    this.mouse = null;
    this.targetCameraPos = null;
    this.targetLookAt = null;
    this.showOrbits = true;
    this.showLabels = true;
  }

  init() {
    if (!this.container || typeof THREE === "undefined") return;

    const width = this.container.clientWidth || window.innerWidth;
    const height = this.container.clientHeight || window.innerHeight;

    // Scene
    this.scene = new THREE.Scene();

    // Camera
    this.camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 5000);
    this.camera.position.set(0, 180, 280);

    // Renderer
    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    this.renderer.setSize(width, height);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.container.innerHTML = "";
    this.container.appendChild(this.renderer.domElement);

    // OrbitControls
    if (THREE.OrbitControls) {
      this.controls = new THREE.OrbitControls(this.camera, this.renderer.domElement);
      this.controls.enableDamping = true;
      this.controls.dampingFactor = 0.05;
      this.controls.maxDistance = 1500;
      this.controls.minDistance = 5;
    }

    // Raycaster
    this.raycaster = new THREE.Raycaster();
    this.mouse = new THREE.Vector2();

    // Build World
    this.buildStarfield();
    this.buildLighting();
    this.buildSun();
    this.buildPlanets();
    this.buildAsteroidBelt();

    // Event Listeners
    window.addEventListener("resize", () => this.onResize());
    this.renderer.domElement.addEventListener("pointerdown", (e) => this.onPointerDown(e));

    this.bindUIControls();
    this.animate();
  }

  buildStarfield() {
    const starCount = 4000;
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(starCount * 3);
    const colors = new Float32Array(starCount * 3);

    for (let i = 0; i < starCount * 3; i += 3) {
      const radius = 1000 + Math.random() * 2000;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos((Math.random() * 2) - 1);

      positions[i] = radius * Math.sin(phi) * Math.cos(theta);
      positions[i + 1] = radius * Math.sin(phi) * Math.sin(theta);
      positions[i + 2] = radius * Math.cos(phi);

      const colorTint = Math.random();
      if (colorTint > 0.8) {
        // Bluish white
        colors[i] = 0.8; colors[i + 1] = 0.9; colors[i + 2] = 1.0;
      } else if (colorTint > 0.6) {
        // Golden
        colors[i] = 1.0; colors[i + 1] = 0.85; colors[i + 2] = 0.6;
      } else {
        colors[i] = 1.0; colors[i + 1] = 1.0; colors[i + 2] = 1.0;
      }
    }

    geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));

    const material = new THREE.PointsMaterial({
      size: 2.2,
      vertexColors: true,
      transparent: true,
      opacity: 0.85
    });

    const starfield = new THREE.Points(geometry, material);
    this.scene.add(starfield);
  }

  buildLighting() {
    // Ambient light for dark sides
    const ambientLight = new THREE.AmbientLight(0x22263a, 0.8);
    this.scene.add(ambientLight);

    // Central Sun light
    const sunLight = new THREE.PointLight(0xffffff, 2.5, 3000, 0.4);
    sunLight.position.set(0, 0, 0);
    this.scene.add(sunLight);
  }

  buildSun() {
    const sunData = SOLAR_SYSTEM_DATA.sun;
    const geometry = new THREE.SphereGeometry(sunData.radiusRel, 48, 48);

    // Canvas procedural texture for Sun surface
    const canvas = document.createElement("canvas");
    canvas.width = 512;
    canvas.height = 256;
    const ctx = canvas.getContext("2d");
    const gradient = ctx.createLinearGradient(0, 0, 512, 256);
    gradient.addColorStop(0, "#ff8800");
    gradient.addColorStop(0.3, "#ffcc00");
    gradient.addColorStop(0.6, "#ff3700");
    gradient.addColorStop(1, "#ffaa00");
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, 512, 256);

    // Add solar granulaton spots
    for (let i = 0; i < 300; i++) {
      ctx.fillStyle = `rgba(255, ${Math.floor(200 + Math.random() * 55)}, 0, ${Math.random() * 0.4})`;
      ctx.beginPath();
      ctx.arc(Math.random() * 512, Math.random() * 256, Math.random() * 12, 0, Math.PI * 2);
      ctx.fill();
    }

    const sunTexture = new THREE.CanvasTexture(canvas);
    const material = new THREE.MeshBasicMaterial({
      map: sunTexture,
      color: 0xffeedd
    });

    const sunMesh = new THREE.Mesh(geometry, material);
    sunMesh.userData = { id: "sun", name: sunData.name };
    this.scene.add(sunMesh);
    this.planets["sun"] = { mesh: sunMesh, data: sunData, angle: 0 };

    // Glowing Corona Layer
    const coronaGeo = new THREE.SphereGeometry(sunData.radiusRel * 1.25, 32, 32);
    const coronaMat = new THREE.MeshBasicMaterial({
      color: 0xff7700,
      transparent: true,
      opacity: 0.28,
      side: THREE.BackSide
    });
    const corona = new THREE.Mesh(coronaGeo, coronaMat);
    this.scene.add(corona);
    this.sunCorona = corona;
  }

  buildPlanets() {
    const planetKeys = ["mercury", "venus", "earth", "mars", "jupiter", "saturn", "uranus", "neptune", "pluto"];

    planetKeys.forEach((key) => {
      const data = SOLAR_SYSTEM_DATA[key];
      if (!data) return;

      // Orbit Line
      const orbitCurve = new THREE.EllipseCurve(
        0, 0,
        data.orbitRadius, data.orbitRadius,
        0, 2 * Math.PI,
        false, 0
      );
      const orbitPoints = orbitCurve.getPoints(120);
      const orbitGeo = new THREE.BufferGeometry().setFromPoints(
        orbitPoints.map(p => new THREE.Vector3(p.x, 0, p.y))
      );
      const orbitMat = new THREE.LineBasicMaterial({
        color: 0x00f3ff,
        transparent: true,
        opacity: 0.18
      });
      const orbitLine = new THREE.Line(orbitGeo, orbitMat);
      this.scene.add(orbitLine);
      this.orbitLines.push(orbitLine);

      // Planet Mesh
      const geometry = new THREE.SphereGeometry(data.radiusRel, 32, 32);
      let material;

      if (key === "earth") {
        material = new THREE.MeshStandardMaterial({
          color: 0x1e66c2,
          roughness: 0.4,
          metalness: 0.1
        });
      } else if (key === "mars") {
        material = new THREE.MeshStandardMaterial({
          color: 0xd65329,
          roughness: 0.8
        });
      } else if (key === "jupiter") {
        material = new THREE.MeshStandardMaterial({
          color: 0xd9a46b,
          roughness: 0.5
        });
      } else if (key === "saturn") {
        material = new THREE.MeshStandardMaterial({
          color: 0xe6cb8c,
          roughness: 0.6
        });
      } else if (key === "venus") {
        material = new THREE.MeshStandardMaterial({
          color: 0xdfb76c,
          roughness: 0.3
        });
      } else if (key === "uranus") {
        material = new THREE.MeshStandardMaterial({
          color: 0x6ce5e8,
          roughness: 0.4
        });
      } else if (key === "neptune") {
        material = new THREE.MeshStandardMaterial({
          color: 0x2e62e6,
          roughness: 0.4
        });
      } else {
        material = new THREE.MeshStandardMaterial({
          color: new THREE.Color(data.color),
          roughness: 0.7
        });
      }

      const mesh = new THREE.Mesh(geometry, material);
      mesh.userData = { id: key, name: data.name };

      // Rings (Saturn & Uranus)
      if (data.rings) {
        const ringGeo = new THREE.RingGeometry(data.rings.innerRadius, data.rings.outerRadius, 64);
        // Rotate ring to align with planet equator
        ringGeo.rotateX(Math.PI / 2.2);
        const ringMat = new THREE.MeshBasicMaterial({
          color: new THREE.Color(data.rings.color),
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.75
        });
        const ringMesh = new THREE.Mesh(ringGeo, ringMat);
        mesh.add(ringMesh);
      }

      // Moon for Earth
      if (key === "earth") {
        const moonGeo = new THREE.SphereGeometry(SOLAR_SYSTEM_DATA.moon.radiusRel, 16, 16);
        const moonMat = new THREE.MeshStandardMaterial({ color: 0xaaaaaa, roughness: 0.9 });
        const moonMesh = new THREE.Mesh(moonGeo, moonMat);
        moonMesh.position.set(SOLAR_SYSTEM_DATA.moon.orbitRadius, 0, 0);
        moonMesh.userData = { id: "moon", name: "The Moon (Luna)" };
        mesh.add(moonMesh);
        this.moonMesh = moonMesh;
      }

      const initialAngle = Math.random() * Math.PI * 2;
      mesh.position.set(
        Math.cos(initialAngle) * data.orbitRadius,
        0,
        Math.sin(initialAngle) * data.orbitRadius
      );

      this.scene.add(mesh);
      this.planets[key] = {
        mesh: mesh,
        data: data,
        angle: initialAngle
      };
    });
  }

  buildAsteroidBelt() {
    const asteroidCount = 1800;
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(asteroidCount * 3);
    const colors = new Float32Array(asteroidCount * 3);

    for (let i = 0; i < asteroidCount * 3; i += 3) {
      const radius = 90 + Math.random() * 18; // Between Mars (78) and Jupiter (110)
      const theta = Math.random() * Math.PI * 2;
      const heightVar = (Math.random() - 0.5) * 5.5;

      positions[i] = Math.cos(theta) * radius;
      positions[i + 1] = heightVar;
      positions[i + 2] = Math.sin(theta) * radius;

      colors[i] = 0.7 + Math.random() * 0.2;
      colors[i + 1] = 0.6 + Math.random() * 0.2;
      colors[i + 2] = 0.5 + Math.random() * 0.2;
    }

    geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));

    const material = new THREE.PointsMaterial({
      size: 1.1,
      vertexColors: true,
      transparent: true,
      opacity: 0.7
    });

    this.asteroidBelt = new THREE.Points(geometry, material);
    this.scene.add(this.asteroidBelt);
  }

  onPointerDown(event) {
    const rect = this.renderer.domElement.getBoundingClientRect();
    this.mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    this.mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;

    this.raycaster.setFromCamera(this.mouse, this.camera);
    const meshes = Object.values(this.planets).map(p => p.mesh);
    if (this.moonMesh) meshes.push(this.moonMesh);

    const intersects = this.raycaster.intersectObjects(meshes, true);

    if (intersects.length > 0) {
      let hit = intersects[0].object;
      while (hit && !hit.userData.id && hit.parent) {
        hit = hit.parent;
      }
      if (hit && hit.userData.id) {
        this.selectPlanet(hit.userData.id);
      }
    }
  }

  selectPlanet(id) {
    this.selectedPlanetId = id;
    sound.playPlanetSelect();
    auth.addXP(25);

    const data = id === "moon" ? SOLAR_SYSTEM_DATA.moon : SOLAR_SYSTEM_DATA[id];
    if (!data) return;

    // Camera fly-to target
    let targetMesh = id === "moon" ? this.moonMesh : (this.planets[id] ? this.planets[id].mesh : null);
    if (targetMesh) {
      const worldPos = new THREE.Vector3();
      targetMesh.getWorldPosition(worldPos);

      const offsetDist = Math.max(data.radiusRel * 4, 12);
      this.targetCameraPos = new THREE.Vector3(
        worldPos.x + offsetDist,
        worldPos.y + (offsetDist * 0.4),
        worldPos.z + offsetDist
      );
      this.targetLookAt = worldPos;
      sound.playWarp();
    }

    this.renderTelemetryHUD(data);
  }

  renderTelemetryHUD(data) {
    const hud = document.getElementById("solarSystemHUD");
    if (!hud) return;

    hud.innerHTML = `
      <div class="glass-panel p-5 border border-cyan-500/40 rounded-xl max-w-sm text-white shadow-2xl animate-fade-in">
        <div class="flex items-center justify-between border-b border-cyan-500/30 pb-3 mb-4">
          <div class="flex items-center space-x-2">
            <span class="w-3 h-3 rounded-full animate-pulse" style="background: ${data.color || '#00f3ff'}"></span>
            <h3 class="text-xl font-bold tracking-wider uppercase text-cyan-300 font-mono">${data.name}</h3>
          </div>
          <button id="closeHudBtn" class="text-gray-400 hover:text-white transition-colors text-lg font-mono">✕</button>
        </div>

        <div class="space-y-2.5 text-xs">
          <div class="flex justify-between py-1 border-b border-white/5">
            <span class="text-gray-400">Classification:</span>
            <span class="font-medium text-cyan-200">${data.type}</span>
          </div>
          <div class="flex justify-between py-1 border-b border-white/5">
            <span class="text-gray-400">Surface Temp:</span>
            <span class="font-medium text-amber-300">${data.surfaceTemp}</span>
          </div>
          <div class="flex justify-between py-1 border-b border-white/5">
            <span class="text-gray-400">Surface Gravity:</span>
            <span class="font-medium text-cyan-200">${data.gravity}</span>
          </div>
          <div class="flex justify-between py-1 border-b border-white/5">
            <span class="text-gray-400">Mass:</span>
            <span class="font-medium text-cyan-200">${data.mass}</span>
          </div>
          <div class="flex justify-between py-1 border-b border-white/5">
            <span class="text-gray-400">Radius:</span>
            <span class="font-medium text-cyan-200">${data.radiusKm.toLocaleString()} km</span>
          </div>
          ${data.orbitPeriodDays ? `
          <div class="flex justify-between py-1 border-b border-white/5">
            <span class="text-gray-400">Orbital Year:</span>
            <span class="font-medium text-cyan-200">${data.orbitPeriodDays} Earth Days</span>
          </div>` : ''}
          ${data.moons !== undefined ? `
          <div class="flex justify-between py-1 border-b border-white/5">
            <span class="text-gray-400">Known Moons:</span>
            <span class="font-medium text-cyan-200">${data.moons}</span>
          </div>` : ''}
        </div>

        <div class="mt-4 pt-3 border-t border-cyan-500/20 text-xs text-gray-300 leading-relaxed">
          <p class="mb-2"><strong class="text-cyan-400">Atmosphere:</strong> ${data.atmosphere}</p>
          <p class="italic text-gray-400">"${data.description}"</p>
        </div>

        ${data.funFact ? `
        <div class="mt-3 p-2.5 bg-cyan-950/40 rounded border border-cyan-500/30 text-[11px] text-cyan-200">
          💡 <strong>NASA Log:</strong> ${data.funFact}
        </div>` : ''}

        ${data.keyMissions ? `
        <div class="mt-3 text-[11px]">
          <span class="text-gray-400 font-semibold">Key Missions:</span>
          <div class="flex flex-wrap gap-1 mt-1">
            ${data.keyMissions.map(m => `<span class="px-2 py-0.5 bg-blue-950/60 text-blue-300 rounded border border-blue-500/30 text-[10px]">${m}</span>`).join('')}
          </div>
        </div>` : ''}
      </div>
    `;

    document.getElementById("closeHudBtn")?.addEventListener("click", () => {
      sound.playClick();
      hud.innerHTML = "";
      this.selectedPlanetId = null;
      this.targetCameraPos = new THREE.Vector3(0, 180, 280);
      this.targetLookAt = new THREE.Vector3(0, 0, 0);
    });
  }

  bindUIControls() {
    // Planet buttons / dropdown
    const planetSelect = document.getElementById("solarPlanetSelect");
    if (planetSelect) {
      planetSelect.addEventListener("change", (e) => {
        if (e.target.value) this.selectPlanet(e.target.value);
      });
    }

    // Time speed controls
    const speedSlider = document.getElementById("solarSpeedSlider");
    const speedDisplay = document.getElementById("solarSpeedDisplay");
    if (speedSlider) {
      speedSlider.addEventListener("input", (e) => {
        this.timeSpeed = parseFloat(e.target.value);
        if (speedDisplay) speedDisplay.innerText = `${this.timeSpeed}x`;
      });
    }

    const pauseBtn = document.getElementById("solarPauseBtn");
    if (pauseBtn) {
      pauseBtn.addEventListener("click", () => {
        sound.playClick();
        this.isPaused = !this.isPaused;
        pauseBtn.innerHTML = this.isPaused ? `<i data-lucide="play"></i> Resume` : `<i data-lucide="pause"></i> Pause`;
        if (window.lucide) window.lucide.createIcons();
      });
    }

    const orbitToggle = document.getElementById("solarOrbitToggle");
    if (orbitToggle) {
      orbitToggle.addEventListener("change", (e) => {
        this.showOrbits = e.target.checked;
        this.orbitLines.forEach(l => l.visible = this.showOrbits);
      });
    }
  }

  animate() {
    this.animationFrameId = requestAnimationFrame(() => this.animate());

    // Rotate Sun & Corona
    if (this.planets["sun"]) {
      this.planets["sun"].mesh.rotation.y += 0.002;
    }
    if (this.sunCorona) {
      this.sunCorona.rotation.z += 0.001;
    }

    // Rotate Asteroid Belt
    if (this.asteroidBelt && !this.isPaused) {
      this.asteroidBelt.rotation.y += 0.0003 * this.timeSpeed;
    }

    // Orbit & Rotate Planets
    if (!this.isPaused) {
      Object.keys(this.planets).forEach((key) => {
        if (key === "sun") return;
        const p = this.planets[key];
        const data = p.data;

        p.angle += (data.orbitSpeed || 0.005) * 0.5 * this.timeSpeed;
        p.mesh.position.x = Math.cos(p.angle) * data.orbitRadius;
        p.mesh.position.z = Math.sin(p.angle) * data.orbitRadius;

        // Axial spin
        p.mesh.rotation.y += 0.01;
      });

      // Orbit Moon around Earth
      if (this.moonMesh) {
        this.moonMesh.rotation.y += 0.02;
      }
    }

    // Smooth Camera Fly-To Lerp
    if (this.targetCameraPos && this.targetLookAt) {
      this.camera.position.lerp(this.targetCameraPos, 0.04);
      if (this.controls) {
        this.controls.target.lerp(this.targetLookAt, 0.04);
      }
      if (this.camera.position.distanceTo(this.targetCameraPos) < 0.5) {
        this.targetCameraPos = null;
        this.targetLookAt = null;
      }
    }

    if (this.controls) {
      this.controls.update();
    }

    this.renderer.render(this.scene, this.camera);
  }

  onResize() {
    if (!this.container || !this.renderer || !this.camera) return;
    const width = this.container.clientWidth;
    const height = this.container.clientHeight;
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(width, height);
  }

  destroy() {
    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
    }
  }
}
